-- PO-1C.2 — Certified Implements & Equipment inventory
-- Source: current Chapter 5 premium quiz bank.
-- Deterministic even-coverage selection: 24 items.

insert into public.comprehensive_exam_questions (
 source_question_id, source_kind, source_chapter_id, domain,
 prompt, option_a, option_b, option_c, option_d,
 correct_option, explanation, content_version, provenance, status
)
values
('qq-5-001','chapter_quiz','5','implements_equipment','A barber needs a comb material that is antistatic and resistant to heat and many chemicals. Which material BEST matches the Chapter 5 source?','Hard rubber','Carbon','Graphite','Metal','b','Read carefully. Identify the keyword: material performance. Eliminate wrong answers: hard rubber is flexible but can deteriorate in disinfectant; graphite is less rigid; metal retains heat and may corrode. Apply safety/procedure logic: match the service need to the source material characteristics. Then make the best remaining choice: carbon.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-003','chapter_quiz','5','implements_equipment','What is the primary purpose of a taper comb?','Detangling wet hair after washing','Blow-drying and styling long hair','Clipper-over-comb and scissor-over-comb tapering with firm grip','Sectioning hair for color applications','c','Taper combs are shorter, sturdier, with teeth spaced to grip hair firmly for clipper-over-comb and scissor-over-comb tapering.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-005','chapter_quiz','5','implements_equipment','Which brush type creates volume and curl during blow-drying?','Paddle brush','Vent brush','Round brush','Pick comb','c','Round brush creates volume and curl. Barrel size matters — larger barrels create bigger curls. Paddle brushes smooth; vent brushes speed drying.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-007','chapter_quiz','5','implements_equipment','A barber wants the shear edge that glides smoothly and is suited to slide cutting. Which edge is the BEST choice?','Convex edge','Beveled edge','Wedge grind','Crocus finish','a','Read carefully. Identify the keyword: slide cutting. Eliminate wrong answers: wedge grind and crocus finish describe straight razors; beveled edges grip hair and are not the source choice for slide cutting. Apply safety/procedure logic: match the shear-edge design to the cutting action. Then make the best remaining choice: convex edge.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-010','chapter_quiz','5','implements_equipment','Which shear part directly adjusts pressure between the moving and still blades?','Tension/pivot screw','Finger rest/tang','Bumper','Shank','a','Read carefully. Identify the keyword: adjusts blade pressure. Eliminate wrong answers: the tang supports the little finger, the bumper limits handle closure, and the shank connects blade to handle. Apply safety/procedure logic: identify the part whose job is to control blade pressure. Then make the best remaining choice: tension/pivot screw.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-012','chapter_quiz','5','implements_equipment','What is the primary purpose of thinning/texturizing shears?','To create blunt, straight lines in the haircut','To remove bulk and create texture without changing overall length','To shave the neckline clean','To disinfect tools between clients','b','Texturizing/thinning shears use toothed blade designs to remove a portion of hair and create texture or reduce bulk. Tooth count and cutting ratio vary by model.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-014','chapter_quiz','5','implements_equipment','What should you NEVER cut with professional shears?','Wet hair','Paper, plastic, wire, or anything other than clean hair','Synthetic hair extensions','Curly hair','b','NEVER cut paper, plastic, wire, or anything other than clean hair. Cutting materials the shear was not designed for can dull, nick, or otherwise damage the edge.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-016','chapter_quiz','5','implements_equipment','Which set names the three clipper motor types identified in the Chapter 5 source?','Rotary, pivot, magnetic','Rotary, hydraulic, lithium','Pivot, ceramic, detachable','Magnetic, carbon, adjustable','a','Read carefully. Identify the keyword: motor types. Eliminate wrong answers: ceramic/carbon are blade materials; detachable/adjustable are clipper systems; lithium describes a battery chemistry. Apply safety/procedure logic: separate motor categories from blade, power, and clipper-type terms. Then make the best remaining choice: rotary, pivot, and magnetic.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-018','chapter_quiz','5','implements_equipment','Clippers begin pulling and snagging during a service. What should the barber do FIRST?','Stop and inspect cleanliness, lubrication, alignment, and blade condition','Assume the client has unusually coarse hair and continue','Immediately replace the motor','Press harder so the blade catches the hair','a','Read carefully. Identify the keyword: FIRST response to pulling. Eliminate wrong answers: continuing, replacing the motor without diagnosis, and adding pressure ignore basic troubleshooting. Apply safety/procedure logic: stop the irritating action and check the source-supported maintenance factors before resuming. Then make the best remaining choice: inspect cleanliness, lubrication, alignment, and condition.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-020','chapter_quiz','5','implements_equipment','Which statement BEST reflects the source''s treatment of cordless clippers?','They offer portability and convenience, but some may have less power than corded models','Lithium-ion models are always stronger than corded clippers','Cordless models never lose cutting power','Battery chemistry alone determines professional quality','a','Read carefully. Identify the keyword: source treatment of cordless clippers. Eliminate wrong answers: the distractors turn convenience into unsupported battery or power absolutes. Apply safety/procedure logic: judge the tool by service needs and manufacturer specifications rather than battery marketing. Then make the best remaining choice: portable and convenient, with possible power tradeoffs.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-022','chapter_quiz','5','implements_equipment','Which comparison between straight-razor types is MOST accurate?','Changeable-blade razors use replaceable blades; conventional straight razors require honing and stropping','Conventional razors use disposable guards; changeable-blade razors require honing','Both types require the same honing schedule','Razor shapers are the same as conventional shaving razors','a','Read carefully. Identify the keyword: razor type distinction. Eliminate wrong answers: the distractors reverse the systems or confuse hair razors with shaving razors. Apply safety/procedure logic: identify whether the edge is replaced or maintained as a permanent blade. Then make the best remaining choice: changeable-blade versus conventional straight razor.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-024','chapter_quiz','5','implements_equipment','When holding a straight razor for shaving, which principle BEST matches the source?','Control the shank/tang area with the taught shaving grip and deliberate blade control','Hold only the cutting edge for maximum precision','Use the same hold as stropping regardless of task','Grip the handle with both hands','a','Read carefully. Identify the keyword: holding for shaving. Eliminate wrong answers: the edge must never be grasped; stropping uses a different task-based hold; two-hand gripping is not the source procedure. Apply safety/procedure logic: the source changes the hold according to the service. Then make the best remaining choice: use the taught shaving hold at the shank/tang area.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-027','chapter_quiz','5','implements_equipment','Which list contains only principal straight-razor parts from the Chapter 5 source?','Head, back, shoulder, tang, point, edge, heel, shank, pivot','Guard, taper lever, motor, heel, cord','Finger rest, bumper, shank, tension screw, thumb grip','Barrel, clamp, swivel, nozzle, diffuser','a','Read carefully. Identify the keyword: straight-razor parts. Eliminate wrong answers: the other lists describe clippers, shears, or thermal tools. Apply safety/procedure logic: match the named parts to the razor anatomy taught in LO10. Then make the best remaining choice: head/back/shoulder/tang/point/edge/heel/shank/pivot.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-029','chapter_quiz','5','implements_equipment','What is a Marcel iron and how is it controlled?','An automatic curling iron with a spring-loaded clamp','A heated comb for textured hair','A type of hair straightener','A manual thermal iron with rotating handle for precise control','d','Marcel iron has a rotating handle for precise temperature and winding control. No spring — the barber controls clamp pressure and rotation.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-031','chapter_quiz','5','implements_equipment','Why should you NEVER use a metal pressing comb directly on the scalp?','It will tangle in the hair','Metal on scalp causes serious burns','It damages the comb','It is against manufacturer warranty','b','Metal on scalp causes serious burns. Always maintain safe distance from skin. Pressing combs straighten hair sections, not touch scalp.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-033','chapter_quiz','5','implements_equipment','What is the best approach to heat protection when using thermal tools?','Use appropriate heat protection, safe temperature selection, and follow product and tool directions','Heat protection matters only for fine hair','Use the highest temperature so the service finishes faster','Heat protection is never useful','a','Thermal-tool safety depends on the hair condition, service, temperature, product directions, and tool guidance. Use appropriate heat protection and avoid excessive heat exposure.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-035','chapter_quiz','5','implements_equipment','Which equipment-role pairing is MOST accurate?','Haircutting cape — protects the client during cutting; neck strip — barrier between cape and skin','Barber chair — disinfects implements; towel — powers clippers','Neck strip — sharpens razors; shampoo cape — adjusts shear tension','Towel — changes clipper length; cape — hones razors','a','Read carefully. Identify the keyword: equipment role. Eliminate wrong answers: the distractors assign tools functions they cannot perform. Apply safety/procedure logic: match each item to its actual service-support function. Then make the best remaining choice: haircutting cape for protection and neck strip as a barrier.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-037','chapter_quiz','5','implements_equipment','Which sequence BEST reflects the source procedure for honing a conventional straight razor?','Use even diagonal strokes, work both sides equally, gradually lighten pressure, then perform the taught edge check','Use heavy pressure on one side until the edge feels rough','Roll the razor on its cutting edge after every stroke','Strop first, then grind only the heel','a','Read carefully. Identify the keyword: honing sequence. Eliminate wrong answers: one-sided heavy pressure and edge-rolling are incorrect; stropping is a different procedure. Apply safety/procedure logic: honing uses controlled abrasive strokes on both sides with pressure reduced as the edge is refined. Then make the best remaining choice: even diagonal strokes, equal sides, lighter pressure, edge check.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-039','chapter_quiz','5','implements_equipment','Which group consists of Chapter 5 equipment used directly to support shaving or comfort services?','Hot-towel cabinet, latherizer, electric massager','Tension screw, finger tang, bumper','Detachable blade, taper lever, guard','Hone, strop, shear case','a','Read carefully. Identify the keyword: equipment supporting service comfort/shaving. Eliminate wrong answers: the other sets are shear, clipper, or blade-maintenance components. Apply safety/procedure logic: match equipment to its service role rather than its material or location. Then make the best remaining choice: hot-towel cabinet, latherizer, electric massager.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-041','chapter_quiz','5','implements_equipment','Which statement about clipper blades and guards is MOST accurate?','Carbon-steel and ceramic are blade materials; 00000 is a very close blade size; guards extend cutting length','00000 is the longest guard and guards replace disinfection','Ceramic is a motor type and carbon steel is a battery type','Guards make outliner blades safe to set flush','a','Read carefully. Identify the keyword: blade material, size, and guard role. Eliminate wrong answers: the distractors mix blade, motor, battery, and sanitation concepts. Apply safety/procedure logic: separate blade material, blade size, and cutting-length aids. Then make the best remaining choice: carbon-steel/ceramic materials, 00000 close size, guards extend length.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-044','chapter_quiz','5','implements_equipment','A barber wants to remove bulk without creating a blunt line. Which shear type is the BEST fit?','Thinning/blending shear with narrow teeth','Straight shear used as a razor','German-style shear because it has no tang','Crane-handle shear regardless of blade type','a','Read carefully. Identify the keyword: remove bulk without a blunt line. Eliminate wrong answers: handle style and tang style do not define the texturizing effect; straight shears are for standard cutting. Apply safety/procedure logic: choose the toothed shear design built to remove a portion of hair. Then make the best remaining choice: thinning/blending shear.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-046','chapter_quiz','5','implements_equipment','What is a razor shaper or hair razor used for?','Texturizing and shaping hair','Honing a conventional straight razor','Disinfecting clipper guards','Applying shaving lather','a','Read carefully. Identify the keyword: razor shaper purpose. Eliminate wrong answers: honing, disinfection, and lather application use different tools. Apply safety/procedure logic: first decide whether the tool is for hair cutting or skin shaving. Then make the best remaining choice: texturizing and shaping hair.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-048','chapter_quiz','5','implements_equipment','SCENARIO: A client wants a skin fade with sharp lines and a beard trim. Which tools are REQUIRED?','Shears and comb only','Just clippers with a #1 guard','Clippers with guards, trimmer, straight razor, and comb','Trimmer and straight razor only','c','Clippers with guards for fade, trimmer for sharp lineup, straight razor for final edge and neck shave, comb for sectioning. Shears alone cannot create a skin fade.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active'),
('qq-5-050','chapter_quiz','5','implements_equipment','A barber is preparing to manipulate a thermal iron. Which sequence is BEST?','Prepare and section the hair, verify safe heat, control the iron, protect the scalp, and move consistently','Heat to maximum temperature, touch the scalp briefly, then section','Clamp one section in place until it smokes','Skip heat testing if the iron was used earlier','a','Read carefully. Identify the keyword: safe thermal-iron sequence. Eliminate wrong answers: maximum heat, scalp contact, stationary overheating, and skipping temperature verification violate safe procedure. Apply safety/procedure logic: thermal manipulation begins with preparation and heat control before consistent movement. Then make the best remaining choice: section, verify heat, control tool, protect scalp, move consistently.','15dc88e5561d05004a066d22a9c7c1e1e095d381',jsonb_build_object('repository_path','src/lib/chapter-5-premium-quiz.ts','repository_commit','15dc88e5561d05004a066d22a9c7c1e1e095d381','selection','po1c2_even_coverage','certification','current_premium_quiz'),'active')
on conflict (source_question_id) do update set
 source_kind=excluded.source_kind, source_chapter_id=excluded.source_chapter_id,
 domain=excluded.domain, prompt=excluded.prompt, option_a=excluded.option_a,
 option_b=excluded.option_b, option_c=excluded.option_c, option_d=excluded.option_d,
 correct_option=excluded.correct_option, explanation=excluded.explanation,
 content_version=excluded.content_version, provenance=excluded.provenance,
 status='active', updated_at=clock_timestamp();

with cfg as (
 select id from public.comprehensive_exam_configs where slug='nic-barber-theory' and version=1
), qs as (
 select id from public.comprehensive_exam_questions where source_question_id in ('qq-5-001','qq-5-003','qq-5-005','qq-5-007','qq-5-010','qq-5-012','qq-5-014','qq-5-016','qq-5-018','qq-5-020','qq-5-022','qq-5-024','qq-5-027','qq-5-029','qq-5-031','qq-5-033','qq-5-035','qq-5-037','qq-5-039','qq-5-041','qq-5-044','qq-5-046','qq-5-048','qq-5-050')
)
insert into public.comprehensive_exam_config_questions
 (config_id,question_id,scored_eligible,unscored_eligible,is_active)
select cfg.id,qs.id,true,true,true from cfg cross join qs
on conflict (config_id,question_id)
do update set scored_eligible=true,unscored_eligible=true,is_active=true;
